CREATE OR REPLACE FUNCTION public.can_edit_project_payment_dates(_project uuid) RETURNS boolean LANGUAGE sql STABLE SECURITY DEFINER SET search_path=public AS $$ SELECT public.pm_phase_a_area_gate(_project,'financials') AND (public.pm_payment_finance_access(_project) OR (auth.uid() IS NOT NULL AND public.is_psa_staff() AND EXISTS(SELECT 1 FROM public.pm_project_team WHERE project_id=_project AND role='manager' AND resource_id=public.pm_unique_viewer_resource()))) $$;